import sys, json, copy, random
sys.path.insert(0,'submission');sys.path.insert(0,'tmp')
from protocol import validate
from te.session import run_case
from verify_replay import verify_request

def case_cycles(mode='admit',W=1,K=2,cycles=20,rho=8,alpha=None,maxlag=12,quorum=None):
    # nodes chain 0-1-2 with one cheap edge capacity1 each and alternate path maybe
    edges=[[0,1,1],[1,2,1],[0,2,10]]
    coms=[]
    for k in range(K):
        coms.append({'source':0,'sink':2,'demand':1000,'paths':[[0,1],[2],None]})
    # partition commodities across workers
    workers=[[] for _ in range(W)]
    for k in range(K): workers[k%W].append(k)
    events=[];tid=0
    for cyc in range(cycles):
        for w in range(W):
            events.append({'op':'issue','id':tid,'worker':w});tid+=1
        for w in range(W):
            events.append({'op':'deliver','id':tid-W+w})
        events.append({'op':'step'})
        events.append({'op':'audit'})
        if cyc%7==3: events.append({'op':'retune','rho':(rho%8)+1})
    return {'nodes':3,'edges':edges,'commodities':coms,'workers':workers,
            'quorum':W if quorum is None else quorum,'max_lag':maxlag,
            'relax':alpha or [1,1],'rho':rho,'mode':mode,'events':events}

def run(req):
    validate(req)
    out={'cases':[run_case(c) for c in req['cases']]}
    verify_request(req,out)
    return out
if __name__=='__main__':
  for mode in ['route','admit']:
    for alpha in [[1,1],[2,1],[15,8]]:
      for W in [1,2,3]:
        for rho in [1,8]:
          req={'cases':[case_cycles(mode,W,min(5,max(1,W*2)),20 if W==1 else 10,rho,alpha)]}
          out=run(req)
          adv=sum(e.get('status')=='advanced' for e in out['cases'][0]['events'] if e['op']=='step')
          print('ok',mode,alpha,W,rho,'adv',adv)
  # no live edges: capacity patch zero all edges, issue/deliver/step route/admit
  req={'cases':[case_cycles('route',1,1,1)]}
  req['cases'][0]['events']=[{'op':'configure','mode':'route','capacity':[[0,0],[1,0],[2,0]],'demand':[],'paths':[]}, {'op':'issue','id':0,'worker':0},{'op':'deliver','id':0},{'op':'step'},{'op':'audit'}]
  run(req);print('ok no live route')
  req['cases'][0]['events'][0]['mode']='admit'
  out=run(req);print('ok no live admit',out)
  print('ALL TARGETED OK')
PY
